//! RTPS's and RTPT's division, H over SZ3, by the reciprocal table and the Newton-Raphson step of psx-spx's "GTE
//! Division Inaccuracy" (BlackMoon_GTE.md §5).

/// psx-spx's `unr_table[000h..100h]`, generated by its own formula `max(0, (40000h/(i+100h)+1)/2-101h)`.
pub const UNR_TABLE: [u8; 0x101] = {
    let mut t = [0u8; 0x101];
    let mut i = 0;
    while i < 0x101 {
        let v = (0x40000 / (i as i32 + 0x100) + 1) / 2 - 0x101;
        t[i] = if v > 0 { v as u8 } else { 0 };
        i += 1;
    }
    t
};

/// The quotient, at most 1FFFFh, and whether it overflowed (FLAG bit 17): H < SZ3*2 divides, anything else is the
/// overflow.
pub fn divide(h: u16, sz3: u16) -> (u32, bool) {
    let (h, sz3) = (h as u32, sz3 as u32);
    if h >= sz3 * 2 {
        return (0x1FFFF, true);
    }
    let z = (sz3 as u16).leading_zeros();
    let n = (h << z) as u64;
    let d = sz3 << z;
    let u = UNR_TABLE[((d - 0x7FC0) >> 7) as usize] as u32 + 0x101;
    let d = (0x0200_0080 - d * u) >> 8;
    let d = (0x0000_0080 + d * u) >> 8;
    (((n * d as u64 + 0x8000) >> 16).min(0x1FFFF) as u32, false)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_psx_spxs() {
        assert_eq!(UNR_TABLE[..16], [0xFF, 0xFD, 0xFB, 0xF9, 0xF7, 0xF5, 0xF3, 0xF1, 0xEF, 0xEE, 0xEC, 0xEA, 0xE8, 0xE6, 0xE4, 0xE3]);
        assert_eq!(UNR_TABLE[0x70..0x80], [0x63, 0x62, 0x61, 0x60, 0x5F, 0x5E, 0x5D, 0x5D, 0x5C, 0x5B, 0x5A, 0x59, 0x58, 0x57, 0x56, 0x55]);
        assert_eq!(UNR_TABLE[0xF0..], [0x07, 0x07, 0x06, 0x06, 0x05, 0x05, 0x04, 0x04, 0x03, 0x03, 0x02, 0x02, 0x01, 0x01, 0x00, 0x00, 0x00]);
    }

    #[test]
    fn the_division_saturates_where_psx_spx_says() {
        assert_eq!(divide(0, 0), (0x1FFFF, true), "by zero");
        assert_eq!(divide(0x100, 0x80), (0x1FFFF, true), "SZ3 <= H/2");
        assert_eq!(divide(0x1000, 0x1000), (0x10000, false));
        assert_eq!(divide(0x0001, 0x0001), (0x10000, false), "d = 20000h");
        assert!(!divide(0xFE3F, 0x7F20).1);
        assert_eq!(divide(0xFE3F, 0x7F20).0, 0x1FFFF, "UNR gives 20000h, saturated without the flag");
        assert_eq!(divide(0xF015, 0x780B), (0x1FFFF, false));
    }
}
